argv:
file_caps="$(getcap /usr/bin/caddy)"
[ "$file_caps" = "/usr/bin/caddy cap_net_bind_service=ep" ]
printf '%s\n' "$file_caps"
awk '
$1 == "Uid:" || $1 == "Gid:" {
  if (NF != 5 || $2 != "0" || $3 != "0" || $4 != "0" || $5 != "0") exit 1
  print $1, $2, $3, $4, $5; count++; next
}
$1 == "CapPrm:" || $1 == "CapEff:" || $1 == "CapBnd:" {
  if (NF != 2 || $2 != "0000000000000400") exit 1
  print $1, $2; count++; next
}
$1 == "NoNewPrivs:" {
  if (NF != 2 || $2 != "1") exit 1
  print $1, $2; count++
}
END { if (count != 6) exit 1 }
' /proc/$$/status
caddy version
caddy validate --config /inputs/ipv4.Caddyfile --adapter caddyfile 1>&2
echo REMISSION_IPV4_VALIDATED
caddy validate --config /inputs/dns.Caddyfile --adapter caddyfile 1>&2
echo REMISSION_DNS_VALIDATED
